#!/usr/bin/env node
// kar-tally — Agensi skill script, generated by build.mjs in the sjgant80-hub/kar-tally repository.
// The KERNEL block below is byte-identical to the logic of the live page (index.html) and to
// kernel.mjs, which the tests and the witness mutation gate run against. No network, no dependencies,
// writes no files: it reads the input you name and prints a JSON report to stdout.
// MIT licence.
// ---- KERNEL (from index.html) ----
var ALGO_VERSION = 'kar-tally-v1';

// ---------- core verifier (pure, deterministic, no I/O) ----------
function verifyLedger(cap, startSeq, entries) {
  if (typeof cap !== 'number' || !isFinite(cap)) {
    return { verdict: 'FAIL', violations: [{ index: -1, seq: null, message: 'cap must be a finite number' }], rows: [], totalSpent: 0, finalBalance: 0 };
  }
  if (!Number.isInteger(startSeq)) {
    return { verdict: 'FAIL', violations: [{ index: -1, seq: null, message: 'startSeq must be an integer' }], rows: [], totalSpent: 0, finalBalance: cap };
  }
  const violations = [];
  const rows = [];
  const capCents = Math.round(cap * 100);
  let runningCents = capCents;
  let expectedSeq = startSeq;

  if (!Array.isArray(entries) || entries.length === 0) {
    return { verdict: 'FAIL', violations: [{ index: -1, seq: null, message: 'entries must be a non-empty array' }], rows: [], totalSpent: 0, finalBalance: cap };
  }

  entries.forEach((raw, i) => {
    const rowMsgs = [];
    const e = (raw !== null && typeof raw === 'object') ? raw : {};
    if (e !== raw) rowMsgs.push('entry must be an object');
    const requiredFields = ['seq', 'actor', 'action', 'cost', 'balance'];
    for (const f of requiredFields) {
      if (!(f in e)) rowMsgs.push('missing field "' + f + '"');
    }
    const seq = e.seq;
    const cost = e.cost;
    const claimedBalance = e.balance;

    if (!(typeof seq === 'number' && Number.isInteger(seq))) rowMsgs.push('seq must be an integer');
    if (!(typeof cost === 'number' && isFinite(cost) && cost >= 0)) rowMsgs.push('cost must be a non-negative finite number');
    if (!(typeof claimedBalance === 'number' && isFinite(claimedBalance))) rowMsgs.push('balance must be a finite number');
    if (!(typeof e.actor === 'string' && e.actor)) rowMsgs.push('actor must be a non-empty string');
    if (!(typeof e.action === 'string' && e.action)) rowMsgs.push('action must be a non-empty string');

    let recomputedBalance = null;
    let capExceeded = false, balanceMismatch = false, seqBreak = false;

    if (typeof seq === 'number' && Number.isInteger(seq)) {
      if (seq !== expectedSeq) {
        seqBreak = true;
        rowMsgs.push('sequence break: expected seq ' + expectedSeq + ', found ' + seq);
      }
      expectedSeq = seq + 1;
    } else {
      expectedSeq = expectedSeq + 1;
    }

    if (typeof cost === 'number' && isFinite(cost)) {
      const costCents = Math.round(cost * 100);
      runningCents -= costCents;
      recomputedBalance = runningCents / 100;
      if (runningCents < 0) {
        capExceeded = true;
        rowMsgs.push('cap exceeded: recomputed balance ' + recomputedBalance.toFixed(2) + ' is below zero');
      }
      if (typeof claimedBalance === 'number' && isFinite(claimedBalance)) {
        const claimedCents = Math.round(claimedBalance * 100);
        if (claimedCents !== runningCents) {
          balanceMismatch = true;
          rowMsgs.push('balance mismatch: claimed ' + claimedBalance.toFixed(2) + ', recomputed ' + recomputedBalance.toFixed(2));
        }
      }
    }

    rows.push({ index: i, seq: seq, actor: e.actor, action: e.action, cost: cost, claimedBalance: claimedBalance, recomputedBalance: recomputedBalance, ok: rowMsgs.length === 0, flags: { capExceeded: capExceeded, balanceMismatch: balanceMismatch, seqBreak: seqBreak }, messages: rowMsgs });
    rowMsgs.forEach(m => violations.push({ index: i, seq: seq, message: m }));
  });

  const verdict = violations.length === 0 ? 'PASS' : 'FAIL';
  return { verdict: verdict, violations: violations, rows: rows, totalSpent: (capCents - runningCents) / 100, finalBalance: runningCents / 100 };
}

function canonicalize(value) {
  if (value === null || typeof value !== 'object') return JSON.stringify(value);
  if (Array.isArray(value)) return '[' + value.map(canonicalize).join(',') + ']';
  const keys = Object.keys(value).sort();
  return '{' + keys.map(k => JSON.stringify(k) + ':' + canonicalize(value[k])).join(',') + '}';
}

async function sha256Hex(str) {
  const buf = new TextEncoder().encode(str);
  const hash = await crypto.subtle.digest('SHA-256', buf);
  return Array.from(new Uint8Array(hash)).map(b => b.toString(16).padStart(2, '0')).join('');
}

// ---------- sample ledgers ----------
const goodEntries = [
  { seq: 1, actor: 'agent-1', action: 'api_call:search',   cost: 40.00, balance: 460.00 },
  { seq: 2, actor: 'agent-1', action: 'api_call:generate', cost: 75.50, balance: 384.50 },
  { seq: 3, actor: 'agent-2', action: 'tool:send_email',   cost: 12.25, balance: 372.25 },
  { seq: 4, actor: 'agent-1', action: 'api_call:generate', cost: 88.00, balance: 284.25 },
  { seq: 5, actor: 'agent-3', action: 'tool:file_write',   cost: 5.00,  balance: 279.25 },
  { seq: 6, actor: 'agent-2', action: 'api_call:search',   cost: 40.00, balance: 239.25 }
];

function makeOverspend() {
  const e = goodEntries.map(x => ({ ...x }));
  e[3] = { seq: 4, actor: 'agent-1', action: 'api_call:generate', cost: 400.00, balance: 20.00 };
  return e;
}
function makeGap() {
  return [goodEntries[0], goodEntries[1], goodEntries[3], goodEntries[4], goodEntries[5]].map(x => ({ ...x }));
}
function makeMismatch() {
  const e = goodEntries.map(x => ({ ...x }));
  e[4] = { ...e[4], balance: 300.00 };
  return e;
}

// SHA-256 of the canonical input (cap + startSeq + entries): the fingerprint a third party recomputes
async function fingerprint(cap, startSeq, entries) {
  return sha256Hex(canonicalize({ cap: cap, startSeq: startSeq, entries: entries }));
}

// ---------- self-test (the page's "Run self-test"; the skill script's --selftest) ----------
const selfTestScenarios = [
  { name: 'Clean ledger', desc: 'Six normal entries, cap=500, nothing altered.', cap: 500, startSeq: 1, entries: goodEntries, expect: 'PASS' },
  { name: 'Hidden overspend', desc: 'Entry 4 cost spiked to 400.00 and its claimed balance was rewritten to hide the overspend.', cap: 500, startSeq: 1, entries: makeOverspend(), expect: 'FAIL' },
  { name: 'Deleted entry', desc: 'Entry seq=3 removed entirely; seq jumps 2 -> 4.', cap: 500, startSeq: 1, entries: makeGap(), expect: 'FAIL' },
  { name: 'Edited balance only', desc: 'Entry 5 claimed balance changed to 300.00; cost left untouched.', cap: 500, startSeq: 1, entries: makeMismatch(), expect: 'FAIL' },
  { name: 'Missing field', desc: 'A single entry with no "action" field.', cap: 500, startSeq: 1, entries: [{ seq: 1, actor: 'a', cost: 1, balance: 499 }], expect: 'FAIL' },
  { name: 'Empty ledger', desc: 'Zero entries submitted for a nonzero cap.', cap: 500, startSeq: 1, entries: [], expect: 'FAIL' }
];

function runSelfTests(list) {
  list = list || selfTestScenarios;
  return list.map(s => {
    const result = verifyLedger(s.cap, s.startSeq, s.entries);
    return { name: s.name, desc: s.desc, expect: s.expect, verdict: result.verdict, ok: result.verdict === s.expect,
      caught: result.violations.length ? result.violations[0].message : '' };
  });
}
// ---- CLI (from cli.mjs) ----
// cli.mjs — Kar-Tally on the command line. build.mjs bundles this with the KERNEL block of index.html into
// scripts/kar-tally.mjs, the single file the Agensi skill runs. It recomputes an agent's spend ledger from the
// cap down, to the cent, and reports every balance that does not add up, every gap in the sequence and every
// point where the cap was exceeded. Exit 0 = PASS · 1 = FAIL (or a self-check failed) · 2 = unusable input.
import { readFileSync } from 'node:fs';

const USAGE = `usage: node kar-tally.mjs <ledger.json | ->
       node kar-tally.mjs --selftest        run the page's built-in tamper scenarios
input:  {"cap": 500, "startSeq": 1, "entries": [{"seq": 1, "actor": "agent-1", "action": "api_call:search",
         "cost": 40.00, "balance": 460.00}, …]}      (startSeq is optional, default 1)
output: a JSON report on stdout. exit 0 = PASS, 1 = FAIL, 2 = bad input`;

class InputError extends Error {}
const fail = (msg) => { throw new InputError(msg); };

function readText(path) {
  try { return readFileSync(path === '-' ? 0 : path, 'utf8'); }
  catch (e) { return fail(`cannot read ${path === '-' ? 'stdin' : path}: ${e.code || e.message}`); }
}

async function tally(input) {
  if (!input || typeof input !== 'object' || Array.isArray(input)) fail('the input must be an object: {"cap", "startSeq", "entries"}');
  const { cap, entries } = input;
  const startSeq = input.startSeq === undefined ? 1 : input.startSeq;
  if (typeof cap !== 'number' || !isFinite(cap)) fail('"cap" must be a number');
  if (!Number.isInteger(startSeq)) fail('"startSeq" must be an integer');
  const result = verifyLedger(cap, startSeq, entries);
  return {
    exitCode: result.verdict === 'PASS' ? 0 : 1,
    report: {
      tool: 'kar-tally',
      algorithm: ALGO_VERSION,
      verdict: result.verdict,
      cap,
      startSeq,
      totalSpent: result.totalSpent,
      finalBalance: result.finalBalance,
      violations: result.violations,
      rows: result.rows,
      fingerprint: await fingerprint(cap, startSeq, entries),
      method: 'The running balance starts at the cap; each entry\'s cost is subtracted in array order, in whole cents. ' +
        'Each seq must equal the previous seq + 1 (the first must equal startSeq), each claimed balance must equal the ' +
        'recomputed balance to the cent, and the recomputed balance must never go below zero. fingerprint = SHA-256 of ' +
        'the canonical JSON of {cap, startSeq, entries} (keys sorted, no whitespace).',
    },
  };
}

async function main(args) {
  if (args.length === 1 && args[0] === '--selftest') {
    const results = runSelfTests();
    const passed = results.filter((t) => t.ok).length;
    process.stdout.write(JSON.stringify({ tool: 'kar-tally', algorithm: ALGO_VERSION, selftest: results, passed, total: results.length }, null, 2) + '\n');
    return passed === results.length ? 0 : 1;
  }
  if (args.length !== 1 || args[0] === '-h' || args[0] === '--help') { process.stderr.write(USAGE + '\n'); return 2; }
  let input;
  try { input = JSON.parse(readText(args[0])); } catch (e) { if (e instanceof InputError) throw e; fail(`the input is not valid JSON (${e.message})`); }
  const { exitCode, report } = await tally(input);
  process.stdout.write(JSON.stringify(report, null, 2) + '\n');
  return exitCode;
}

try {
  process.exitCode = await main(process.argv.slice(2));
} catch (e) {
  process.stderr.write(`kar-tally: ${e instanceof InputError ? e.message : 'internal error: ' + (e && e.message)}\n`);
  process.exitCode = e instanceof InputError ? 2 : 3;
}
